import{_ as t,o,c as n,a2 as a}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Portfolio and connected accounts","description":"Unified portfolio total, source attribution, manual positions, duplicate-exposure warnings, valuations, freshness, and portfolio activity.","frontmatter":{"title":"Portfolio and connected accounts","description":"Unified portfolio total, source attribution, manual positions, duplicate-exposure warnings, valuations, freshness, and portfolio activity.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"use-zenin/portfolio-and-connected-accounts.md","filePath":"use-zenin/portfolio-and-connected-accounts.md","lastUpdated":null}'),s={name:"use-zenin/portfolio-and-connected-accounts.md"};function i(r,e,l,c,d,u){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="portfolio-and-connected-accounts" tabindex="-1">Portfolio and connected accounts</h1><p>Portfolio is where connected accounts and manual positions come together so you can see total exposure in one place.</p><h2 id="unified-portfolio-total" tabindex="-1">Unified portfolio total</h2><p>The total combines:</p><ul><li><strong>Connected holdings</strong> imported from your brokerage, exchange, or watch-only sources.</li><li><strong>Cash balances</strong> where the source provides them.</li><li><strong>Manual positions</strong> you added directly.</li></ul><h2 id="source-attribution" tabindex="-1">Source attribution</h2><p>Every position shows which source it came from. This matters because:</p><ul><li>Connected data is tagged with the originating connection.</li><li>Manual data is tagged <strong>manual</strong>.</li><li>You can see, at a glance, how much of your view depends on each source.</li></ul><h2 id="manual-positions" tabindex="-1">Manual positions</h2><p>Add manual positions for assets outside your connections (for example, an account you have not linked yet). Manual entries:</p><ul><li>are attributed as <strong>manual</strong> so they are never confused with imported data;</li><li>count toward totals and exposure like any other position.</li></ul><h2 id="duplicate-exposure-warnings" tabindex="-1">Duplicate-exposure warnings</h2><p>If the same instrument appears in more than one source (for example, the same holding in a brokerage and an exchange), Zenin flags <strong>duplicate exposure</strong> rather than silently doubling it. The unified view reconciles the overlap so your total is not overstated.</p><h2 id="valuations" tabindex="-1">Valuations</h2><p>Valuations use the best available price for each instrument:</p><ul><li><strong>Live or delayed</strong> market data when the provider supplies it.</li><li><strong>Reference / last-known</strong> values when live data is unavailable, clearly marked by freshness state.</li></ul><p>Zenin does not invent a price it cannot source.</p><h2 id="freshness" tabindex="-1">Freshness</h2><p>Each position carries a freshness state (<strong>current, delayed, stale, unavailable, reference-only</strong>). Review the <a href="/use-zenin/data-status-glossary">Data status glossary</a> to interpret them.</p><h2 id="portfolio-activity" tabindex="-1">Portfolio activity</h2><p>Portfolio activity shows recent imports and sync events, so you can verify when data last changed and trace a missing value back to its source.</p><hr><h2 id="what-this-does-does-not-do" tabindex="-1">What this does / does not do</h2><p><strong>What this does</strong></p><ul><li>Aggregates connected and manual positions into one total with per-source attribution.</li><li>Warns on duplicate exposure across sources.</li><li>Surfaces freshness and valuation basis per position.</li></ul><p><strong>What it does not do</strong></p><ul><li>It does not execute trades or move money.</li><li>It does not &quot;fix&quot; missing prices — it marks them with a freshness state.</li><li>It does not assume every connected venue supports the same coverage.</li></ul><p><strong>Data source and freshness</strong></p><p>Holdings and balances come from your connected read-only sources (SnapTrade brokerage, exchange API keys, Hyperliquid watch-only). Prices come from the configured market-data provider and may be current, delayed, stale, or reference-only by instrument.</p>',29)])])}const f=t(s,[["render",i]]);export{h as __pageData,f as default};
